xm4 N009 N008 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4} l={L_xm4}
xm3 N008 N008 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm3} l={L_xm3}
xm6t N013 N014 N016 N010 sky130_fd_pr__nfet_01v8 w={W_xm6t} l={L_xm6t}
xm6b N016 N015 N010 N010 sky130_fd_pr__nfet_01v8 w={W_xm6b} l={L_xm6b}
