C1 vm1 N010 1e-05
R1 vm1 Vout 100000000.0
Cc Vout N012 2.4e-12
C3 Vout N010 1e-13
Rz N009 N012 6500.0

xm5 N002 N003 N005 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
xm6 N001 vm N005 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
