R2 vm AOL 100000000.0
Cc1 AOL N004 2.4e-12
C4 AOL 0 1e-13
Rz1 N002 N004 6500.0
xm15 N014 N014 N015 N010 sky130_fd_pr__nfet_01v8 w={W_xm15} l={L_xm15}
xm16 N015 N015 N010 N010 sky130_fd_pr__nfet_01v8 w={W_xm16} l={L_xm16}
