  xma12 N008 Vbias1 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma12} l={L_xma12}
  xm16 Vncas Vncas N012 0 sky130_fd_pr__nfet_01v8 w={W_xm16} l={L_xm16}
  xm17 N012 Vbias3 P001 0 sky130_fd_pr__nfet_01v8 w={W_xm17} l={L_xm17}
  xm18 P001 N012 0 0 sky130_fd_pr__nfet_01v8 w={W_xm18} l={L_xm18}
.ends SUB_1

* --- Added Sources for floating inputs ---
* N011 is the non-inverting input of Op-amp 1 (Vout)
* N003 is the non-inverting input of Op-amp 2 (AOL)
V_N011 N011 0 DC 0.9 AC 1
V_N003 N003 0 DC 0.9 AC 0

.control
  * AC Analysis
  ac dec 100 1 1G

  * Op-amp 1 (Vout) has AC 1 on its input N011.
  * vdb(Vout) is the open-loop gain.
  let aol_db = vdb(Vout)
  let aol_phase = 180/PI * cph(v(Vout))
  meas ac aol_dc find aol_db at=1
  meas ac fun when aol_db=0 fall=1
  meas ac pm find aol_phase when aol_db=0 fall=1

  * Op-amp 2 (AOL) has AC 1 on VDD, AC 0 on input N003.
  * vdb(AOL) is the gain from VDD to output.
  * PSRR+ = Open-Loop Gain (dB) - VDD Gain (dB)
  let psrr_plus_db = aol_db - vdb(AOL)
  meas ac psrr_plus_dc find psrr_plus_db at=1

  print aol_dc fun pm psrr_plus_dc
  quit
.endc
.end

